import logging
from taf.collectors.core.util.string_formatting import partial_format
from taf.collectors.core.entities.executor import ExecutionError

from taf.converters.base import NToNConverterObject

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TtiTracerConverter(NToNConverterObject):
    """
    Converter of 4G TTI trace *.dat files to *.txt and *.txt.harq output files
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(
            self,
            options=None,
            ttitracer_directory="/opt/TtiTracer",
            duplex="fdd",
            **kwargs):
        """
        Create a converter to convert 4G TTI trace *.dat files to *.txt and *.txt.harq output files.

        :param Optional[str] options:
            optional arguments to Ttitracer exceutable, default is empty string
        :param Optional[str] ttitracer_directory
            directory where TtiTracer.zip is installed, default is /opt/TtiTracer
        """
        self._ttitracer_directory = ttitracer_directory
        self._sudo_prefix = ''
        self._options = " " + options if options else ""
        self._duplex = duplex

        super(TtiTracerConverter, self).__init__(command_template=None, **kwargs)

    def _setup(self):
        self._sudo_prefix = self._executor.sudo_prefix()

        command_find_ttitracer_exe = ("find '{ttitracer_directory}/TtiTracer' -name DevC_tti_trace_parser_64".format(
            ttitracer_directory=self._ttitracer_directory)
            if self._duplex == "tdd"
            else "find '{ttitracer_directory}/TtiTracer' -name tti_trace_parser_wmp-linux.exe".format(
                ttitracer_directory=self._ttitracer_directory))

        self._ttitracer_path = self._executor.execute(command_find_ttitracer_exe.encode('utf-8')).decode('utf-8').strip()

        self._ttitracer_commands_list = [
            "{ttitracer_path} {input_file_path}".format(
                ttitracer_path=self._ttitracer_path,
                input_file_path=input_file,
            ) for input_file in self._finder.find()
        ]

        try:
            self._executor.execute(
                '{sudo_prefix}pkill -9 -f -x "{ttitracer_commands_list}"'.format(
                    sudo_prefix=self._sudo_prefix,
                    ttitracer_commands_list='|'.join(
                        self._ttitracer_commands_list)).encode('utf-8')
            )
        except ExecutionError as exception:
            logger.debug("Terminating TtiTracer process failed: %r", exception)

        command_template = partial_format("'{ttitracer_path}' '{input_file}' '{output_file}'{options}",
                                          ttitracer_path=self._ttitracer_path,
                                          options=self._options
                                          )

        self._command_template = command_template

        command_change_file_permissions = "{sudo_prefix}chmod u+x {ttitracer_path}".format(
            ttitracer_path=self._ttitracer_path,
            sudo_prefix=self._sudo_prefix
        )
        self._executor.execute(command_change_file_permissions.encode('utf-8'))

    def _teardown(self):
        try:
            self._executor.execute(
                '{sudo_prefix}pkill -9 -f -x "{ttitracer_commands_list}"'.format(
                    sudo_prefix=self._sudo_prefix,
                    ttitracer_commands_list='|'.join(
                        self._ttitracer_commands_list)).encode('utf-8')
            )
        except ExecutionError as exception:
            logger.debug("Terminating TtiTracer process failed: %r", exception)
